#!/usr/bin/env bash
# live-smoke.sh - OPTIONAL, not part of run.sh. Drives the real `claude -p` (haiku, ~US$0.10 total) in
# bypassPermissions with the hooks generated by install.sh, to confirm the real hook engine accepts our
# schemas: guard deny, SessionStart additionalContext, Stop block. Everything lives under /tmp; user
# settings are excluded with --setting-sources project. install.sh is fully sandboxed under /tmp: it gets
# CLAUDE_DIR, SETTINGS_FILE, AGENT_REPOS_FILE, AGENT_HOME, LAUNCH_AGENTS_DIR and a no-op LAUNCHCTL, so it
# cannot touch the real ~/.claude (hook symlink, settings), ~/.agent-repos, ~/Library/LaunchAgents or launchd.
# The generated hooks run through $S/claude/kaching -> this checkout, so the smoke test exercises this
# checkout's hooks, not the installed ones. HOME is left alone on purpose: `claude -p` needs it for auth.
# Section 4 speaks one sentence (day time only). Section 5 is silent: tests/live-watch.sh, read-only, on the real launchd job.
set -euo pipefail
KIT=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
REAL_AGENT_HOME=${AGENT_HOME:-$HOME/.agent}   # section 5 looks at the real machine, read-only
S=$(mktemp -d /tmp/kaching-live.XXXXXX)
export AGENT_HOME="$S/agent-home" NOTIFY_DRY_RUN=1 NOTIFY_LOG="$S/notify.log"
export GIT_AUTHOR_NAME=t GIT_AUTHOR_EMAIL=t@e GIT_COMMITTER_NAME=t GIT_COMMITTER_EMAIL=t@e
# the smoke test checks hooks, not model escalation, and must not start paid Haiku/Sonnet fix attempts
export KACHING_TEST_MODELS=""
mkdir -p "$S/claude" "$S/repo"
CLAUDE_DIR="$S/claude" SETTINGS_FILE="$S/claude/settings.json" AGENT_REPOS_FILE="$S/agent-repos" \
  LAUNCH_AGENTS_DIR="$S/LaunchAgents" LAUNCHCTL=/usr/bin/true "$KIT/install.sh" --yes >/dev/null
cd "$S/repo"; git init -q -b main; git commit -q --allow-empty -m init
mkdir .agent
printf 'test_command: test -f %s/repo/ok-file\nrelease_mode: confirm\n' "$S" >.agent/GOAL.md
printf '# State\nThe secret word is PINEAPPLE-42.\n' >.agent/STATE.md
run() { claude -p --model haiku --permission-mode bypassPermissions --setting-sources project --settings "$S/claude/settings.json" \
          --max-budget-usd 0.30 --no-session-persistence "$1" </dev/null 2>&1 | tail -n 15; }

echo "== 0. SessionStart injection alone (expects PINEAPPLE-42), repo with GOAL.md but no test_command"
mkdir -p "$S/repo0/.agent"; (cd "$S/repo0" && git init -q -b main && git commit -q --allow-empty -m init)
printf 'release_mode: confirm\n' >"$S/repo0/.agent/GOAL.md"; printf '# State\nThe secret word is PINEAPPLE-42.\n' >"$S/repo0/.agent/STATE.md"
(cd "$S/repo0" && run 'What is the secret word from your agent state context? Answer with just the word.')
echo "== 1. SessionStart injection + Stop block (expects: PINEAPPLE-42, ok-file created after a block)"
run 'What is the secret word from your agent state context? Answer in one line. If you are told a done-check failed, create an empty file named ok-file in the current directory, then finish.'
echo "retries/last state:"; cat "$AGENT_HOME"/sessions/*/meta 2>/dev/null | grep -E '^(state|cwd)=' || true
echo "ok-file exists: $([ -f ok-file ] && echo yes || echo no)"
echo "events logged: $(jq -r .kind "$AGENT_HOME/events.jsonl" 2>/dev/null | sort | uniq -c | tr -s ' \n' ' ')"
echo "== 2. guard denies a force push in bypass mode (to a scratch branch, so the model has no reason to refuse by itself)"
git remote add origin "$S/remote.git"; git init -q --bare "$S/remote.git"
run 'Run exactly this command with the Bash tool and report what happened in one line: git push --force origin HEAD:scratch'
echo "remote has scratch: $(git --git-dir="$S/remote.git" rev-parse -q --verify refs/heads/scratch >/dev/null && echo YES-BAD || echo no-good)"
echo "== 4. check-in nudge: real voice and idle read (you should hear one short sentence)"
if "$KIT/bin/speak.sh" "Kaching check-in test."; then echo "speak.sh: ok"; else echo "speak.sh: FAILED (is Kokoro running on port 8880?)"; fi
# ioreg lives in /usr/sbin (not on launchd's PATH). awk exits at the first match and ioreg may get SIGPIPE (141):
# with set -eo pipefail that must not end the script before the idle value and the sandbox line are printed.
idle=$(/usr/sbin/ioreg -c IOHIDSystem | awk '/"HIDIdleTime"/ { print int($NF / 1000000000); exit }' || true)
echo "keyboard/mouse idle seconds: ${idle:-UNREADABLE}"
echo "== 5. launchd watcher on the real machine (silent, read-only; --kick would also start one extra run)"
AGENT_HOME="$REAL_AGENT_HOME" "$KIT/tests/live-watch.sh" || echo "live-watch: problems above (this does not fail the smoke run)"
echo "sandbox: $S"
